edits.sketch:
v_old text := '- Rely on the cascade: ... so your override wins.';
v_at := position(v_old in v_prompt);
IF v_at = 0 THEN RAISE EXCEPTION '390/616 drift: ... not present verbatim ...'; END IF;
IF position(v_old in substr(v_prompt, v_at + length(v_old))) > 0 THEN RAISE EXCEPTION '390/616 drift: ... appears more than once ...'; END IF;

IF position('Repeat the offending selector exactly as it appears above' in v_prompt) > 0 THEN RAISE EXCEPTION ...; END IF;
IF position('"css_added"' in v_prompt) = 0 OR position('"changes_summary"' in v_prompt) = 0 THEN RAISE EXCEPTION '... output contract damaged ...'; END IF;
SELECT count(*) INTO v_dangling FROM (... next_step/error_step/then_step/else_step ...) WHERE tgt IS NOT NULL AND NOT (v_steps ? tgt);
